    23	            {
    24	              scale: 1,
    25	              opacity: 1,
    26	              ease: "none",
    27	              scrollTrigger: {
    28	                trigger: media,
    29	                start: "top 90%",
    30	                end: "center 55%",
    31	                scrub: true,
    32	              },
    33	            },
    34	          );
    35	        });
    36	
    37	      gsap.utils
    38	        .toArray<HTMLElement>("[data-stack-card]")
    39	        .forEach((card, index) => {
    40	          ScrollTrigger.create({
    41	            trigger: card,
    42	            start: `top ${96 + index * 18}px`,
    43	            endTrigger: "[data-stack]",
    44	            end: "bottom bottom",
    45	            pin: true,
    46	            pinSpacing: false,
    47	          });
    48	        });
    49	    },
    50	    { scope },
    51	  );
    52	
    53	  return <div ref={scope}>{children}</div>;
    54	}
